mapper.insert:
INSERT INTO carts (
    user_id,
    created_at
) VALUES (
    #{userId},
    #{createdAt}
)

mapper.update:
UPDATE cart_items
SET quantity = #{quantity}
WHERE cart_item_id = #{cartItemId}

mapper.select:
SELECT ci.cart_item_id AS cartItemId, ci.cart_id AS cartId, ci.item_id AS itemId, ci.quantity, ci.added_at AS addedAt, i.title AS itemTitle, i.price, i.item_image_url AS itemImageUrl, i.user_id AS sellerId, CASE WHEN i.user_id = -1 THEN '系统商品' ELSE u.username END AS sellerName FROM cart_items ci JOIN items i ON ci.item_id = i.item_id LEFT JOIN users u ON i.user_id = u.user_id WHERE ci.cart_item_id IN
#{id}
ORDER BY ci.added_at DESC
